package com.petlis.service.impl;
import com.fasterxml.jackson.databind.ObjectMapper;import com.petlis.common.exception.BusinessException;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.context.annotation.Import;import org.springframework.transaction.annotation.Transactional;
import java.util.*;import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest @Import(LegacyBankJdbcTestConfiguration.class) @Transactional("legacyBankTestTransactions") @EnabledIfEnvironmentVariable(named="PETLIS_LOCAL_DB_TEST",matches="true")
class LegacyCustomerMonthLocalDatabaseTest {
 @Autowired FeatureStore store;@Autowired ObjectMapper json;LegacyCustomerViewLocalDatabaseTest fixture;LegacyBankPaymentQuoteLocalDatabaseTest f;LegacyCustomerViewService service;
 @BeforeEach void setup(){fixture=new LegacyCustomerViewLocalDatabaseTest();fixture.store=store;fixture.json=json;fixture.setup();f=fixture.f;service=fixture.service;}
 @Test void monthIncludesLastSecondAndExemptItemsExactlyAsSource(){store.jdbc().update("UPDATE lin_lb_listdiagnosisproject SET ReceiveSampleDt='2024-02-29 23:59:59' WHERE ListDiagnosisProjectId=?",f.order);f.detail(f.test,"7.25",0,0);f.detail(f.test,"1.00",1,0);f.detail(f.test,"2.00",0,1);var result=service.month(new LegacyCustomerViewService.MonthCommand(f.hospital,null,"2024-02",null));var rows=rows(result);assertEquals(1,rows.size());assertEquals("10.25",rows.get(0).get("TestPrice"));assertEquals("1.00",rows.get(0).get("totalHasPayFee"));assertEquals("9.25",rows.get(0).get("totalNoPayFee"));assertEquals(true,rows.get(0).get("representativeAmbiguous"));store.jdbc().update("UPDATE lin_lb_listdiagnosisproject SET ReceiveSampleDt='2024-03-01 00:00:00' WHERE ListDiagnosisProjectId=?",f.order);assertEquals(0,rows(service.month(new LegacyCustomerViewService.MonthCommand(f.hospital,null,"2024-02",null))).size());}
 @Test void userNoLookupDoesNotSilentlyAddMonthFilterAndLeavesMonthListIntact(){f.detail(f.test,"3.00",0,0);var result=service.month(new LegacyCustomerViewService.MonthCommand(f.hospital,null,"2024-02",f.prefix));assertTrue(rows(result).isEmpty());@SuppressWarnings("unchecked")var project=(Map<String,Object>)result.get("project");assertEquals(f.prefix,project.get("UserNO"));assertEquals(1,((List<?>)result.get("items")).size());assertEquals(f.order,((Number)project.get("ListDiagnosisProjectId")).longValue());}
 @Test void oldMonthTokenAndValidationRemainControlled(){String token=LegacyLinkCodec.encrypt(String.valueOf(f.hospital),"public-customer-view-test");assertEquals(f.hospital,((Number)service.month(new LegacyCustomerViewService.MonthCommand(null,token,"2024-02",null)).get("hospitalId")).longValue());assertEquals(400,assertThrows(BusinessException.class,()->service.month(new LegacyCustomerViewService.MonthCommand(f.hospital,null,"2024-13",null))).getCode());store.jdbc().update("UPDATE lin_operational_config SET config_value='{\"enabled\":false}' WHERE config_key='legacy-customer-views'");assertEquals(409,assertThrows(BusinessException.class,()->service.month(new LegacyCustomerViewService.MonthCommand(f.hospital,null,"2024-02",null))).getCode());}
 @Test void originalHundredGroupLimitIsExplicitAndUserNoCanReachAnotherGroup(){long first=f.order;for(int i=0;i<101;i++){if(i>0)f.order=LegacyDetailFixtures.order(store,f.prefix+"_limit_"+i,f.actor);store.jdbc().update("UPDATE lin_lb_listdiagnosisproject SET InfoHospitalId=?,InfoAnimalId=(SELECT MIN(InfoAnimalId) FROM lin_lb_infoanimal),ReceiveSampleDt='2024-02-15 12:00:00' WHERE ListDiagnosisProjectId=?",f.hospital,f.order);f.detail(f.test,"1.00",0,0);}f.order=first;var result=service.month(new LegacyCustomerViewService.MonthCommand(f.hospital,null,"2024-02",null));assertEquals(100,rows(result).size());assertEquals(101L,((Number)result.get("totalGroups")).longValue());assertEquals(true,result.get("limited"));result=service.month(new LegacyCustomerViewService.MonthCommand(f.hospital,null,"2024-02",f.prefix));assertNotNull(result.get("project"));assertEquals(100,rows(result).size());}
 @SuppressWarnings("unchecked")List<Map<String,Object>> rows(Map<String,Object> result){return (List<Map<String,Object>>)result.get("orders");}
 @Test void originalUserNoLookupCanSpanHospitalsButPreviewWarnsWithoutChangingScope(){f.detail(f.test,"1.00",0,0);long otherHospital=store.insert("INSERT INTO lin_lb_infohospital(HospitalName,HospitalName_en,PayType,amount) VALUES(?,?,1,0)",f.prefix+"_other",f.prefix+"_other");long original=f.order;f.order=LegacyDetailFixtures.order(store,f.prefix,f.actor);store.jdbc().update("UPDATE lin_lb_listdiagnosisproject SET InfoHospitalId=?,InfoAnimalId=(SELECT MIN(InfoAnimalId) FROM lin_lb_infoanimal),ReceiveSampleDt='2024-02-15 12:00:00' WHERE ListDiagnosisProjectId=?",otherHospital,f.order);f.detail(f.test,"2.00",0,0);f.order=original;var result=service.month(new LegacyCustomerViewService.MonthCommand(f.hospital,null,"2024-02",f.prefix));assertEquals(true,result.get("crossHospitalSource"));assertEquals(2,((List<?>)result.get("items")).size());@SuppressWarnings("unchecked")var hospital=(Map<String,Object>)result.get("queryHospital");assertEquals(f.hospital,((Number)hospital.get("InfoHospitalId")).longValue());}
}
